mapper.select:
SELECT id, user_id, endpoint, idempotency_key, request_hash, response_code,
       response_json, status, expires_at, create_time, update_time
FROM sys_idempotency_record
WHERE user_id = #{userId}
  AND endpoint = #{endpoint}
  AND idempotency_key = #{idempotencyKey}

mapper.delete:
DELETE FROM sys_idempotency_record
WHERE expires_at < NOW()
LIMIT #{limit}
